// Modo: Run Once for All Items
const filtros = $('When Executed by Another Workflow').first().json;
const linhas = $input.all().map(i => i.json);

const norm = v => String(v ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/\s+/g, ' ').trim();

// lê coluna ignorando acento/caixa no cabeçalho (CÓDIGO ou CODIGO, etc.)
const col = (row, nome) => {
  const alvo = norm(nome);
  for (const k of Object.keys(row)) if (norm(k) === alvo) return row[k];
  return undefined;
};

const num = v => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d,.-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
};

const preenchido = v => v !== undefined && v !== null && String(v).trim() !== '';
const escapaRegex = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// só linhas de dados (ignora nota de rodapé / linhas vazias)
const dados = linhas.filter(r => num(col(r, 'CODIGO')) !== null);
const unicos = (rows, c) => [...new Set(rows.map(r => col(r, c)).filter(v => preenchido(v)))];

// contém (texto livre): "couche brilho 300" acha "Couché Brilho 300g"
const contem = (valorLinha, filtro) => norm(valorLinha).includes(norm(filtro));
// começa uma palavra: "4 paginas" NÃO acha "24 Páginas"; "2 dobras" acha "2 Dobras Sanfona"
const comecaPalavra = (valorLinha, filtro) =>
  new RegExp('(^|\\s)' + escapaRegex(norm(filtro))).test(norm(valorLinha));

// se o texto pedido existe exatamente na tabela, exige igual (evita "Verniz ... Frente" pegar "Verniz ... Frente e Verso");
// senão, aceita "contém"
const valoresExatos = {};
for (const c of ['MATERIAL', 'ENOBRECIMENTO', 'ACABAMENTO']) valoresExatos[c] = new Set(unicos(dados, c).map(norm));
const casaTexto = (valorLinha, filtro, coluna) =>
  valoresExatos[coluna].has(norm(filtro)) ? norm(valorLinha) === norm(filtro) : contem(valorLinha, filtro);

// ---------- produto ----------
const SINONIMOS_SERVICO = {
  panfleto: 'folheto', flyer: 'folheto',
  talao: 'bloco e talao autocopiativo', autocopiativo: 'bloco e talao autocopiativo',
  recibo: 'bloco de recibo', pedido: 'bloco de pedido',
  catalogo: 'catalogo premium',
};
const servicosNorm = [...new Set(dados.map(r => norm(col(r, 'SERVICO'))))];

// devolve os produtos da planilha que combinam com o que o cliente disse
function resolverServico(v) {
  let s = norm(v);
  if (!s) return { servicos: [], modeloHint: '' };
  let modeloHint = '';
  const d = s.match(/(\d+)\s*dobras?/);
  if (d) modeloHint = `${d[1]} dobra`;
  const p = s.match(/(\d+)\s*pag/);
  if (p) modeloHint = `${p[1]} paginas`;
  for (const [de, para] of Object.entries(SINONIMOS_SERVICO)) {
    if (new RegExp('\\b' + de + '\\b').test(s) && !s.includes(para)) { s = para; break; }
  }
  const servicos = servicosNorm.filter(x => s.includes(x) || x.includes(s));
  return { servicos, modeloHint };
}

// ---------- tamanho ----------
function normFormato(v) {
  const m = norm(v).replace(/mm|cm/g, '').replace(/[×*]/g, 'x').replace(/\s/g, '').match(/(\d+[.,]?\d*)x(\d+[.,]?\d*)/);
  if (!m) return null;
  return [m[1], m[2]].map(n => parseFloat(n.replace(',', '.')));
}
const igual = (x, y) => Math.abs(x - y) < 0.01;

// formatoTabela está sempre em mm; o pedido pode vir em cm ("10x14cm"), mm ou sem unidade.
// exato = mesma orientação (148x210 ≠ 210x148); sem exato, aceita girado.
function casaFormato(formatoTabela, pedido) {
  const ft = normFormato(formatoTabela), fp = normFormato(pedido);
  if (!ft || !fp) return { casa: false, exato: false };
  const p = norm(pedido);
  const escalas = p.includes('mm') ? [1] : p.includes('cm') ? [10] : [1, 10];
  let casa = false, exato = false;
  for (const e of escalas) {
    const a = fp[0] * e, b = fp[1] * e;
    if (igual(ft[0], a) && igual(ft[1], b)) { casa = true; exato = true; }
    else if (igual(ft[0], b) && igual(ft[1], a)) casa = true;
  }
  return { casa, exato };
}

// tamanhos vão pro cliente em cm ("14,8 × 21 cm"); a planilha guarda em mm
const cmTxt = mm => String(Math.round(mm) / 10).replace('.', ',');
const formatoCm = f => { const d = normFormato(f); return d ? `${cmTxt(d[0])} × ${cmTxt(d[1])} cm` : String(f); };
const areaFormato = f => { const d = normFormato(f); return d ? d[0] * d[1] : 0; };
const formatosCm = lista => [...lista].sort((a, b) => areaFormato(a) - areaFormato(b)).map(formatoCm);

// tamanho pedido -> o da lista mais parecido (aceita girado); sem unidade, número grande = mm, pequeno = cm
function formatoMaisProximo(pedido, listaMm) {
  const fp = normFormato(pedido);
  if (!fp || !listaMm.length) return '';
  const p = norm(pedido);
  const e = p.includes('mm') ? 1 : p.includes('cm') ? 10 : (Math.max(fp[0], fp[1]) >= 60 ? 1 : 10);
  const w = fp[0] * e, h = fp[1] * e;
  let melhor = null, dMelhor = Infinity;
  for (const f of listaMm) {
    const d = normFormato(f);
    if (!d) continue;
    const dist = Math.min(Math.abs(d[0] - w) + Math.abs(d[1] - h), Math.abs(d[0] - h) + Math.abs(d[1] - w));
    if (dist < dMelhor) { dMelhor = dist; melhor = f; }
  }
  return melhor ? formatoCm(melhor) : '';
}

// ---------- impressão ----------
const IMPRESSAO = {
  '4x0': { lado: 'frente',       cor: 'colorida', desc: 'Só frente, colorida' },
  '4x4': { lado: 'frente_verso', cor: 'colorida', desc: 'Frente e verso, coloridos' },
  '4x1': { lado: 'frente_pb',    cor: 'misto',    desc: 'Frente colorida e verso preto e branco' },
  '1x0': { lado: 'frente',       cor: 'uma_cor',  desc: 'Só frente, uma cor' },
  '1x1': { lado: 'frente_verso', cor: 'uma_cor',  desc: 'Frente e verso, escala de cinza' },
};
const infoImp = codigo => IMPRESSAO[norm(codigo)] || { lado: norm(codigo), cor: '', desc: String(codigo ?? '') };

// em bloco/talão o verso normalmente fica em branco: "frente e verso" = personalizar também o verso
const ehBloco = servico => /^bloco/.test(norm(servico));
const DESC_BLOCO = {
  '1x0': 'Só na frente, em uma cor',
  '1x1': 'Frente e verso, em escala de cinza',
  '4x0': 'Só na frente, colorido',
  '4x4': 'Frente e verso, colorido',
};
const descImp = (codigo, servico) => (ehBloco(servico) && DESC_BLOCO[norm(codigo)]) || infoImp(codigo).desc;
const rotuloImp = servico => ehBloco(servico) ? 'Personalização' : 'Impressão';

// "frente e verso", "so frente", "4x4", "1x1", "preto e branco"... -> lado + código preferido
function lerImpressao(v) {
  const s = norm(v);
  if (!s) return null;
  const cod = s.match(/\b(4x0|4x1|4x4|1x0|1x1)\b/);
  const umaCor = /(preto|cinza|\bpb\b|uma cor|1 cor|monocrom)/.test(s);
  let lado;
  if (cod) lado = IMPRESSAO[cod[1]].lado;
  else if (s.includes('verso') && umaCor && /colorid/.test(s)) lado = 'frente_pb';   // "frente colorida e verso preto e branco"
  else if (s.includes('verso')) lado = 'frente_verso';
  else lado = 'frente';
  const preferido = cod ? cod[1]
    : lado === 'frente' ? (umaCor ? '1x0' : '4x0')
    : lado === 'frente_verso' ? (umaCor ? '1x1' : '4x4')
    : '4x1';
  return { lado, preferido, exato: !!cod };
}

// ---------- quantidade ----------
function normQtde(v) {
  const s = norm(v);
  if (!s) return null;
  const mil = /\bmil\b/.test(s);
  const n = num(s.replace(/\bmil\b/, ''));
  if (n === null) return null;
  return mil ? n * 1000 : n;
}

// ---------- tipos / modelo (só o que o cliente precisa escolher) ----------
// produtos em que o mesmo papel+verniz existe em vários "modelos" (dobras do folder, páginas do catálogo)
const modeloIndependente = new Set();
{
  const grupos = new Map();
  for (const r of dados) {
    const k = [col(r, 'SERVICO'), col(r, 'MATERIAL'), col(r, 'ENOBRECIMENTO')].join('|');
    if (!grupos.has(k)) grupos.set(k, new Set());
    if (preenchido(col(r, 'MODELO'))) grupos.get(k).add(col(r, 'MODELO'));
  }
  for (const [k, s] of grupos) if (s.size > 1) modeloIndependente.add(k.split('|')[0]);
}
// produtos que têm verniz/laminação de verdade (bloco não tem: não faz sentido falar disso)
const servicoComVerniz = new Set(
  dados.filter(r => norm(col(r, 'ENOBRECIMENTO')) !== 'sem enobrecimento').map(r => col(r, 'SERVICO'))
);

const semEnob = r => norm(col(r, 'ENOBRECIMENTO')) === 'sem enobrecimento' || !preenchido(col(r, 'ENOBRECIMENTO'));
const tiposDe = rows => [...new Set(rows.map(r => {
  const base = String(col(r, 'MATERIAL'));
  if (!servicoComVerniz.has(col(r, 'SERVICO'))) return base;
  return `${base} - ${semEnob(r) ? 'sem verniz/laminação' : col(r, 'ENOBRECIMENTO')}`;
}))];

const unidadeQtde = servico => /^bloco/.test(norm(servico)) ? 'blocos' : 'unidades';

function opcoes(rows) {
  const servs = unicos(rows, 'SERVICO');
  const perguntarModelo = servs.some(s => modeloIndependente.has(s)) && unicos(rows, 'MODELO').length > 1;
  const o = {
    servicos: servs,
    perguntar_modelo: perguntarModelo,
    tipos: tiposDe(rows),
    formatos: formatosCm(unicos(rows, 'FORMATO')),
    impressoes: unicos(rows, 'IMPRESSAO').map(c => ({ codigo: c, descricao: descImp(c, servs[0]) })),
    acabamentos: unicos(rows, 'ACABAMENTO'),
    quantidades: unicos(rows, 'QTDE').map(Number).sort((a, b) => a - b),
    unidade_quantidade: unidadeQtde(servs[0]),
  };
  if (perguntarModelo) o.modelos = unicos(rows, 'MODELO');
  return o;
}

// =================== filtros ===================
const f = {
  servico: filtros.servico, modelo: filtros.modelo, formato: filtros.formato,
  quantidade: filtros.quantidade, material: filtros.material, gramatura: filtros.gramatura,
  impressao: filtros.impressao, acabamento: filtros.acabamento, enobrecimento: filtros.enobrecimento,
};
const nenhumFiltro = Object.values(f).every(v => !preenchido(v));
if (nenhumFiltro) {
  return [{ json: {
    status: 'escolher_produto',
    mensagem: 'Nenhum filtro informado. Estes são os produtos disponíveis.',
    servicos: unicos(dados, 'SERVICO'),
  } }];
}

const { servicos: servicosAlvo, modeloHint } = resolverServico(f.servico);
const modeloFiltro = preenchido(f.modelo) ? f.modelo : modeloHint;

// "sem verniz", "sem laminação", "nenhum" etc. = "Sem Enobrecimento" da planilha
const enobFiltro = /^(sem|nenhum|nao)\b/.test(norm(f.enobrecimento)) ? 'sem enobrecimento' : f.enobrecimento;
const imp = lerImpressao(f.impressao);

// tudo, menos tamanho e quantidade (esses dois têm tratamento próprio)
let base = dados.filter(r => {
  if (preenchido(f.servico) && !servicosAlvo.includes(norm(col(r, 'SERVICO')))) return false;
  if (preenchido(modeloFiltro) && !comecaPalavra(col(r, 'MODELO'), modeloFiltro)) return false;
  if (preenchido(f.material) && !casaTexto(col(r, 'MATERIAL'), f.material, 'MATERIAL')) return false;
  if (preenchido(f.gramatura)) {
    const g = String(f.gramatura).replace(/\D/g, '');
    if (g && String(col(r, 'GRAMATURA')).replace(/\D/g, '') !== g) return false;
  }
  if (imp && infoImp(col(r, 'IMPRESSAO')).lado !== imp.lado) return false;
  if (preenchido(f.acabamento) && !casaTexto(col(r, 'ACABAMENTO'), f.acabamento, 'ACABAMENTO')) return false;
  if (preenchido(f.enobrecimento) && !casaTexto(col(r, 'ENOBRECIMENTO'), enobFiltro, 'ENOBRECIMENTO')) return false;
  return true;
});

if (base.length === 0) {
  const doServico = preenchido(f.servico) ? dados.filter(r => servicosAlvo.includes(norm(col(r, 'SERVICO')))) : [];
  return [{ json: {
    status: 'nao_encontrado',
    mensagem: doServico.length
      ? 'Esse produto existe, mas nenhuma variação bate com essas características.'
      : 'Produto não encontrado na tabela.',
    opcoes_disponiveis: doServico.length ? opcoes(doServico) : { servicos: unicos(dados, 'SERVICO') },
  } }];
}

if (preenchido(f.formato)) {
  const achados = base.map(r => ({ r, ...casaFormato(col(r, 'FORMATO'), f.formato) })).filter(x => x.casa);
  if (achados.length === 0) {
    return [{ json: {
      status: 'formato_nao_encontrado',
      mensagem: `Tamanho ${f.formato} não disponível para esse produto.`,
      formato_mais_proximo: formatoMaisProximo(f.formato, unicos(base, 'FORMATO')),
      formatos_disponiveis: formatosCm(unicos(base, 'FORMATO')),
    } }];
  }
  const exatos = achados.filter(x => x.exato);
  base = (exatos.length ? exatos : achados).map(x => x.r);
}

if (preenchido(f.quantidade)) {
  const q = normQtde(f.quantidade);
  const porQtde = base.filter(r => num(col(r, 'QTDE')) === q);
  if (porQtde.length === 0) {
    return [{ json: {
      status: 'quantidade_nao_encontrada',
      mensagem: `Quantidade ${f.quantidade} não disponível para essa combinação.`,
      quantidades_disponiveis: unicos(base, 'QTDE').map(Number).sort((a, b) => a - b),
      unidade_quantidade: unidadeQtde(unicos(base, 'SERVICO')[0]),
    } }];
  }
  base = porQtde;
}

// impressão: se o cliente não disse cor, prefere colorida; se essa não existir no produto, mantém a que existe
let impressaoAlternativas = [];
if (imp) {
  const pref = base.filter(r => norm(col(r, 'IMPRESSAO')) === imp.preferido);
  if (pref.length) {
    // outras opções do mesmo lado que ficaram de fora (ex: existe também "uma cor"), pra o agente avisar
    impressaoAlternativas = [...new Set(base
      .filter(r => infoImp(col(r, 'IMPRESSAO')).lado === imp.lado && norm(col(r, 'IMPRESSAO')) !== imp.preferido)
      .map(r => descImp(col(r, 'IMPRESSAO'), col(r, 'SERVICO'))))];
    base = pref;
  }
}

// corte: com o tamanho já definido, se o cliente não pediu nenhum e existe "Refile", usa Refile
if (!preenchido(f.acabamento) && unicos(base, 'FORMATO').length === 1) {
  const acs = unicos(base, 'ACABAMENTO');
  if (acs.length > 1 && acs.some(a => norm(a) === 'refile')) {
    base = base.filter(r => norm(col(r, 'ACABAMENTO')) === 'refile');
  }
}

// VALOR FINAL vem direto da planilha (coluna VALOR FINAL)
const valorFinal = r => num(col(r, 'VALOR FINAL'));

// com muitas linhas ainda em aberto, não devolve preços (evita o agente cotar uma linha aleatória)
const LIMITE = 5;
const resultados = base.length <= LIMITE ? base.map(r => ({
  codigo: num(col(r, 'CODIGO')),
  produto: col(r, 'SERVICO'),
  tipo: modeloIndependente.has(col(r, 'SERVICO')) ? col(r, 'MODELO') : '',
  formato: formatoCm(col(r, 'FORMATO')),
  material: col(r, 'MATERIAL'),
  gramatura: col(r, 'GRAMATURA'),
  verniz_laminacao: semEnob(r) ? '' : col(r, 'ENOBRECIMENTO'),
  acabamento: col(r, 'ACABAMENTO'),
  impressao: col(r, 'IMPRESSAO'),
  impressao_rotulo: rotuloImp(col(r, 'SERVICO')),
  impressao_descricao: descImp(col(r, 'IMPRESSAO'), col(r, 'SERVICO')),
  impressao_tambem_existe: impressaoAlternativas,
  quantidade: num(col(r, 'QTDE')),
  unidade_quantidade: unidadeQtde(col(r, 'SERVICO')),
  valor_final: valorFinal(r),
  extras_disponiveis: col(r, 'EXTRAS_DISPONIVEIS') || '',
})) : [];

return [{ json: {
  status: base.length === 1 ? 'encontrado' : 'varios_resultados',
  total: base.length,
  mostrando: resultados.length,
  resultados,
  opcoes_restantes: base.length > 1 ? opcoes(base) : undefined,
} }];
